#include "chimera/process_vm.h"
namespace {
constexpr uint64_t PAGE=4096, ADDR_MASK=0x000FFFFFFFFFF000ull, USER_LIMIT=0x0000800000000000ull;
constexpr uint32_t PF_X=1u,PF_W=2u,PF_R=4u;
struct Region {uint64_t base,physical,size;uint32_t pages;bool used;};
struct Table {uint64_t physical;bool used;};
chimera_x86_vm_ops g_ops{};void*g_context=nullptr;bool g_ready=false;
static void zero(void*p,uint64_t n){auto*b=static_cast<uint8_t*>(p);for(uint64_t i=0;i<n;++i)b[i]=0;}
static bool add_ok(uint64_t a,uint64_t b,uint64_t*out){if(a>UINT64_MAX-b)return false;*out=a+b;return true;}
static bool canonical_user_range(uint64_t base,uint64_t size){uint64_t end=0;return size&&base>=PAGE&&!(base&(PAGE-1))&&!(size&(PAGE-1))&&add_ok(base,size,&end)&&end<=USER_LIMIT;}
}
struct chimera_x86_address_space {uint64_t pml4_phys;uint64_t*pml4;Region regions[CHIMERA_X86_VM_MAX_REGIONS];Table tables[CHIMERA_X86_VM_MAX_TABLES];uint32_t table_count;bool used;};
static uint64_t*table_ptr(uint64_t physical){return static_cast<uint64_t*>(g_ops.physical_to_virtual(g_context,physical));}
static uint64_t*new_table(chimera_x86_address_space*s,uint64_t*entry){if(s->table_count>=CHIMERA_X86_VM_MAX_TABLES)return nullptr;uint64_t phys=0;void*alias=nullptr;if(g_ops.alloc_pages(g_context,1,&phys,&alias)!=0||!alias)return nullptr;zero(alias,PAGE);s->tables[s->table_count++]={phys,true};*entry=(phys&ADDR_MASK)|CHIMERA_X86_PTE_PRESENT|CHIMERA_X86_PTE_WRITABLE|CHIMERA_X86_PTE_USER;return static_cast<uint64_t*>(alias);}
static uint64_t*ensure_child(chimera_x86_address_space*s,uint64_t*parent,uint32_t idx){uint64_t e=parent[idx];if(e&CHIMERA_X86_PTE_PRESENT){if(!(e&CHIMERA_X86_PTE_USER)||(e&CHIMERA_X86_PTE_HUGE))return nullptr;return table_ptr(e&ADDR_MASK);}return new_table(s,&parent[idx]);}
static int map_one(chimera_x86_address_space*s,uint64_t va,uint64_t pa,uint32_t flags){const uint32_t a=(uint32_t)((va>>39)&511),b=(uint32_t)((va>>30)&511),c=(uint32_t)((va>>21)&511),d=(uint32_t)((va>>12)&511);if(a>=256)return -1;uint64_t*l3=ensure_child(s,s->pml4,a);if(!l3)return -2;uint64_t*l2=ensure_child(s,l3,b);if(!l2)return -2;uint64_t*l1=ensure_child(s,l2,c);if(!l1)return -2;if(l1[d]&CHIMERA_X86_PTE_PRESENT)return -3;uint64_t p=CHIMERA_X86_PTE_PRESENT|CHIMERA_X86_PTE_USER|(pa&ADDR_MASK);if(flags&PF_W)p|=CHIMERA_X86_PTE_WRITABLE;if(!(flags&PF_X))p|=CHIMERA_X86_PTE_NX;l1[d]=p;return 0;}
extern "C" int chimera_x86_vm_init(const chimera_x86_vm_ops*ops,void*context){if(!ops||!ops->alloc_pages||!ops->free_pages||!ops->physical_to_virtual||!ops->boot_pml4_physical||!ops->nx_enabled)return -1;void*boot=ops->physical_to_virtual(context,ops->boot_pml4_physical);if(!boot)return -2;g_ops=*ops;g_context=context;g_ready=true;return 0;}
extern "C" chimera_x86_address_space*chimera_x86_vm_create(void){if(!g_ready)return nullptr;uint64_t phys=0;void*alias=nullptr;if(g_ops.alloc_pages(g_context,1,&phys,&alias)!=0||!alias)return nullptr;auto*s=static_cast<chimera_x86_address_space*>(alias);zero(s,PAGE);s->pml4_phys=phys;s->pml4=static_cast<uint64_t*>(alias);s->used=true;s->tables[s->table_count++]={phys,true};auto*boot=static_cast<uint64_t*>(g_ops.physical_to_virtual(g_context,g_ops.boot_pml4_physical));if(!boot){g_ops.free_pages(g_context,phys,1);return nullptr;}for(uint32_t i=256;i<512;++i)s->pml4[i]=boot[i];return s;}
extern "C" int chimera_x86_vm_map(chimera_x86_address_space*s,uint64_t va,uint64_t size,uint32_t flags,void**alias){if(alias)*alias=nullptr;if(!g_ready||!s||!s->used||!alias||!canonical_user_range(va,size)||(flags&~(PF_R|PF_W|PF_X))||(flags&(PF_W|PF_X))==(PF_W|PF_X))return -1;uint64_t end=va+size;for(uint32_t i=0;i<s->table_count;++i)if(s->tables[i].used&&s->tables[i].physical==s->pml4_phys)return -2;uint32_t slot=CHIMERA_X86_VM_MAX_REGIONS;for(uint32_t i=0;i<CHIMERA_X86_VM_MAX_REGIONS;++i){if(!s->regions[i].used){if(slot==CHIMERA_X86_VM_MAX_REGIONS)slot=i;continue;}uint64_t re=s->regions[i].base+s->regions[i].size;if(va<re&&s->regions[i].base<end)return -3;}if(slot==CHIMERA_X86_VM_MAX_REGIONS)return -4;uint32_t pages=(uint32_t)(size/PAGE);uint64_t physical=0;void*kernel_alias=nullptr;if(g_ops.alloc_pages(g_context,pages,&physical,&kernel_alias)!=0||!kernel_alias)return -5;for(uint32_t i=0;i<pages;++i){int rc=map_one(s,va+(uint64_t)i*PAGE,physical+(uint64_t)i*PAGE,flags);if(rc){g_ops.free_pages(g_context,physical,pages);return -6;}}s->regions[slot]={va,physical,size,pages,true};*alias=kernel_alias;return 0;}
extern "C" void chimera_x86_vm_destroy(chimera_x86_address_space*s){if(!s||!s->used||!g_ready)return;for(uint32_t i=0;i<CHIMERA_X86_VM_MAX_REGIONS;++i)if(s->regions[i].used)g_ops.free_pages(g_context,s->regions[i].physical,s->regions[i].pages);uint64_t pml4=s->pml4_phys;for(uint32_t i=s->table_count;i>1;--i)if(s->tables[i-1].used)g_ops.free_pages(g_context,s->tables[i-1].physical,1);zero(s,PAGE);g_ops.free_pages(g_context,pml4,1);}
extern "C" uint64_t chimera_x86_vm_pml4_physical(const chimera_x86_address_space*s){return s&&s->used?s->pml4_phys:0;}
static void*loader_create(void*){return chimera_x86_vm_create();}
static int loader_map(void*,void*space,uint64_t va,uint64_t size,uint32_t flags,void**alias){return chimera_x86_vm_map(static_cast<chimera_x86_address_space*>(space),va,size,flags,alias);}
static void loader_destroy(void*,void*space){chimera_x86_vm_destroy(static_cast<chimera_x86_address_space*>(space));}
extern "C" int chimera_x86_vm_make_loader_ops(chimera_elf_load_ops*out){if(!out||!g_ready)return -1;out->create_address_space=loader_create;out->map_pages=loader_map;out->destroy_address_space=loader_destroy;return 0;}
